import{_ as t,o as r,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-3-create-agency/report3_spec.md","filePath":"feature/agency-workspace/3-4-3-create-agency/report3_spec.md"}'),i={name:"feature/agency-workspace/3-4-3-create-agency/report3_spec.md"};function s(a,e,l,g,c,d){return r(),n("div",null,[...e[0]||(e[0]=[o("<p><strong>3.4.3 Create Agency</strong></p><p><strong>Function Trigger</strong></p><p>A signed-in user submits the Create Agency form, from the Agencies page (/agencies/create) or a dialog opened on that page.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Signed-in user, who becomes the Owner of the Agency being created.</li><li><strong>Purpose</strong>: Let a user open a new Agency on BrandHub and start running their communications company from it.</li><li><strong>Interface</strong>: Create Agency page or dialog — a form with a required name field and optional branding fields (logo, description, category, company size, website, phone, location, brand colour, logo icon, tagline, founded year, Facebook, LinkedIn, Instagram links).</li><li><strong>Data Processing</strong>: The system validates the form, stores a new Agency with the current user as Owner and status ACTIVE, and records the same user as an Agency Member at the OWNER role in the same operation. The logo is uploaded afterwards, once the Agency has an identifier.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Create Agency form:</p><ul><li>Name (required) and the optional branding fields listed above.</li><li>A logo picker: the file is uploaded after the Agency is created, not through the form itself.</li><li>A submit action; on success the user is taken into the newly created Agency.</li><li>The form is reachable from the Agencies page, where an empty state also offers the same call to action.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name of the Agency.</li><li><strong>Input optional</strong>: logoUrl, description, category, companySize, website, phone, location, brandColor (hex, max 9 chars), logoIcon, tagline (max 140 chars), foundedYear, facebookUrl, linkedinUrl, instagramUrl.</li><li><strong>System data</strong>: the Agency record — id, name, ownerId, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status, createdAt, updatedAt — and the Agency Member record pairing the Agency with its Owner at the OWNER role.</li><li><strong>Output</strong>: the profile of the newly created Agency, including its identifier, Owner and status ACTIVE. The logo upload returns the same profile with the logo filled in.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-24 (analogous)</strong>: creating an Agency inserts the creator as an Agency Member with role OWNER, mirroring the workspace-creation rule. Name is mandatory; an empty name is refused with 400 VALIDATION_ERROR.</li><li>Brand colour is limited to 9 characters and tagline to 140 characters; a longer value is refused with 400 VALIDATION_ERROR.</li><li>The creator becomes the Owner and an Agency Member record at OWNER role is created for the same user; the pairing is fixed and cannot be reassigned by any other feature in the current scope.</li><li>The logo is not part of the main form; it is uploaded as a file through the Agency logo upload once the Agency identifier exists. A logo URL may still be passed as text, but the standard journey uploads the file separately.</li><li>On success the user is taken into the newly created Agency.</li><li>A user may own any number of Agencies; no creation limit in the current scope.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Name empty → Display: <strong>MSG02</strong></li><li>Brand colour over 9 characters, or tagline over 140 characters → Display: <strong>MSG03</strong></li><li>No signed-in session → 401 UNAUTHORIZED before any Agency logic runs.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens the Create Agency form and fills in the name and, optionally, the branding fields.</li><li>The client submits the form.</li><li>The system validates the values against the rules above.</li><li>The system stores a new Agency with the current user as its Owner and status ACTIVE.</li><li>The system stores an Agency Member record with the OWNER role for that same user.</li><li>The system returns the profile of the new Agency and the client moves the user into it; toast <strong>MSG31</strong>.</li><li>The user optionally uploads a logo file; the system stores the file, fills in the logo, and returns the updated profile; toast <strong>MSG94</strong>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Name left empty → 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>; nothing is created. 3.a2: The user fills in the name and resubmits.</li><li>3.b1: Brand colour or tagline over its limit → 400 VALIDATION_ERROR, Display: <strong>MSG03</strong>; nothing is created. 3.b2: The user shortens the field and resubmits.</li><li>1.a1: No signed-in session → 401 UNAUTHORIZED, toast <strong>MSG22</strong>. 1.a2: The user signs in again and retries.</li><li>7.a1: The logo file fails to be read → 400 FILE_READ_ERROR, toast <strong>MSG29</strong>; the Agency itself remains created. 7.a2: The user selects a valid file and retries the upload.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A new Agency exists with the current user as its Owner and status ACTIVE.</li><li>An Agency Member record with the OWNER role exists for that user.</li><li>If a logo was uploaded, the Agency profile carries the logo URL and a refreshed update timestamp.</li></ul>",14)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
